import anyio
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import Response

async def endpoint(scope, receive, send):
    try:
        raise LookupError('application context')
    except LookupError:
        raise RuntimeError('application error')

async def passthrough(request, call_next):
    return await call_next(request)

app = BaseHTTPMiddleware(endpoint, dispatch=passthrough)
scope = {'type': 'http', 'asgi': {'version': '3.0'}, 'http_version': '1.1', 'method': 'GET', 'scheme': 'http', 'path': '/', 'raw_path': b'/', 'query_string': b'', 'headers': [], 'client': None, 'server': None}
async def receive(): return {'type': 'http.request', 'body': b'', 'more_body': False}
async def send(message): pass
async def main():
    try:
        await app(scope, receive, send)
    except RuntimeError as exc:
        print(type(exc.__cause__).__name__ if exc.__cause__ else None, type(exc.__context__).__name__ if exc.__context__ else None, exc.__suppress_context__)
anyio.run(main)
PY"

